import crypto from 'node:crypto';
import { promisify } from 'node:util';

/* ---------- Neon Postgres over HTTPS (no npm package needed) ---------- */
// Same protocol the official @neondatabase/serverless driver uses: POST the query to the database host's /sql endpoint.
const PG = { BOOL: 16, INT8: 20, INT2: 21, INT4: 23, OID: 26, FLOAT4: 700, FLOAT8: 701, JSON: 114, JSONB: 3802, TS: 1114, TSTZ: 1184 };
function pgIso(v) {
  const d = new Date(String(v).replace(' ', 'T').replace(/([+-]\d\d)$/, '$1:00'));
  return isNaN(d) ? v : d.toISOString();
}
function pgParse(v, type) {
  if (v === null || v === undefined) return null;
  switch (type) {
    case PG.BOOL: return v === true || v === 't' || v === 'true';
    case PG.INT2: case PG.INT4: case PG.OID: case PG.FLOAT4: case PG.FLOAT8: return Number(v);
    case PG.JSON: case PG.JSONB: return typeof v === 'string' ? JSON.parse(v) : v;
    case PG.TS: case PG.TSTZ: return pgIso(v);
    default: return v; // int8 / numeric stay strings, like the official driver
  }
}
function pgParam(v) {
  if (v === undefined || v === null) return null;
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (v instanceof Date) return v.toISOString();
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
}
function neon(connectionString) {
  const u = new URL(String(connectionString).replace(/^postgres(ql)?:/, 'https:'));
  const host = u.hostname.replace('-pooler.', '.');
  const endpoints = [`https://${host.replace(/^[^.]+\./, 'api.')}/sql`, `https://${host}/sql`];
  let good = null;
  async function run(query, params) {
    const body = JSON.stringify({ query, params: params.map(pgParam) });
    const headers = { 'Content-Type': 'application/json', 'Neon-Connection-String': connectionString, 'Neon-Raw-Text-Output': 'true', 'Neon-Array-Mode': 'true' };
    let lastErr;
    for (const ep of good ? [good] : endpoints) {
      let r;
      try { r = await fetch(ep, { method: 'POST', headers, body }); } catch (e) { lastErr = e; continue; }
      if (!good && (r.status === 404 || r.status === 405)) { lastErr = new Error(`Database endpoint not found (${ep})`); continue; }
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { const e = new Error('Database: ' + (j.message || `HTTP ${r.status}`)); e.code = j.code; throw e; }
      good = ep;
      const fields = j.fields || [];
      return (j.rows || []).map(row => {
        const o = {};
        if (Array.isArray(row)) fields.forEach((f, i) => { o[f.name] = pgParse(row[i], f.dataTypeID); });
        else fields.length ? fields.forEach(f => { o[f.name] = pgParse(row[f.name], f.dataTypeID); }) : Object.assign(o, row);
        return o;
      });
    }
    throw lastErr || new Error('Database unreachable');
  }
  return (strings, ...vals) => {
    let q = strings[0];
    vals.forEach((_, i) => { q += '$' + (i + 1) + strings[i + 1]; });
    return run(q, vals);
  };
}


