// Shared helpers for GainPlus+ API routes. Files starting with "_" are not deployed as routes on Vercel.

const scrypt = promisify(crypto.scrypt);

const PLANS = ['none', 'demo', 'vip30', 'lifetime', 'admin'];
// Key prefixes: VIP = lifetime access, 30D = 30 days, DEMO = 8 hours, ADM = admin.
const KEY_TYPES = { admin: 'ADM', vip30: '30D', lifetime: 'VIP', demo: 'DEMO' };
// Master key that opens the admin account from the VIP screen. Override with the ADMIN_LICENSE_KEY env var.
const masterKey = () => (process.env.ADMIN_LICENSE_KEY || 'GAIN-LIFE-2006-4GMS').trim().toUpperCase();
const adminName = () => (process.env.ADMIN_USERNAME || 'admin').trim().toLowerCase();
const PREVIEW_HOURS = 2;
const DEMO_HOURS = 8;
const VIP_DAYS = 30;

function httpErr(status, message) { const e = new Error(message); e.status = status; return e; }

let _sql;
function db() {
  if (!_sql) {
    if (!process.env.DATABASE_URL) throw httpErr(500, 'DATABASE_URL is not set on the server');
    _sql = neon(process.env.DATABASE_URL);
  }
  return _sql;
}

