function send(res, status, obj) {
  res.setHeader('Cache-Control', 'no-store');
  res.status(status).json(obj);
}

function wrap(fn) {
  return async (req, res) => {
    try {
      await ready();
      await fn(req, res);
    } catch (e) {
      if (!e.status) console.error(e);
      send(res, e.status || 500, { error: e.status ? e.message : 'Server error. Check the Vercel function logs.' });
    }
  };
}

function body(req) {
  let b = req.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch { b = {}; } }
  return b || {};
}

/* ---------- Passwords ---------- */
async function hashPw(pw) {
  const salt = crypto.randomBytes(16);
  const h = await scrypt(pw, salt, 64);
  return `s1$${salt.toString('hex')}$${h.toString('hex')}`;
}
async function checkPw(pw, stored) {
  const [v, s, h] = String(stored || '').split('$');
  if (v !== 's1' || !s || !h) return false;
  const got = await scrypt(String(pw), Buffer.from(s, 'hex'), 64);
  const exp = Buffer.from(h, 'hex');
  return exp.length === got.length && crypto.timingSafeEqual(exp, got);
}
function safeEqual(a, b) {
  const x = Buffer.from(String(a)), y = Buffer.from(String(b));
  return x.length === y.length && crypto.timingSafeEqual(x, y);
}

/* ---------- Session tokens (HMAC-signed; account is re-checked on every request) ---------- */
let _secret = null;
function secret() {
  const s = process.env.AUTH_SECRET && process.env.AUTH_SECRET.length >= 16 ? process.env.AUTH_SECRET : _secret;
  if (!s) throw httpErr(500, 'Server secret not ready');
  return s;
}
// Installs the preset XML bot exactly once (the settings row makes this safe if several servers start together).
// It becomes the only enabled bot at that moment. If the admin deletes it later, it is not re-added.
async function installPresetBot(sql) {
  const won = await sql`INSERT INTO gp_settings (key, value) VALUES (${PRESET_BOT.key}, '1') ON CONFLICT (key) DO NOTHING RETURNING key`;
  if (!won.length) return;
  const p = parseDbotXml(PRESET_BOT.xml);
  const entry = PRESET_BOT.entry || (p.rule ? 'signal_xml' : 'signal');   // the hot scan bot follows the tool's own signal
  await sql`UPDATE gp_bots SET enabled = false`;
  await sql`INSERT INTO gp_bots (name, xml, symbol, contract_type, barrier, duration, duration_unit, stake, entry, rule, enabled, created_by)
    VALUES (${PRESET_BOT.name}, ${PRESET_BOT.xml}, ${p.symbol}, ${p.contract_type}, ${p.barrier}, ${p.duration}, ${p.duration_unit},
            ${p.stake}, ${entry}, ${p.rule ? JSON.stringify(p.rule) : null}, true, 'preset')`;
}
async function loadSecret(sql) {
  if (process.env.AUTH_SECRET && process.env.AUTH_SECRET.length >= 16) return;
  await sql`INSERT INTO gp_settings (key, value) VALUES ('auth_secret', ${crypto.randomBytes(32).toString('hex')}) ON CONFLICT (key) DO NOTHING`;
  const [r] = await sql`SELECT value FROM gp_settings WHERE key = 'auth_secret'`;
  _secret = r.value;
}
function signToken(uid, days, extra = {}) {
  const p = Buffer.from(JSON.stringify({ uid, exp: Date.now() + days * 864e5, ...extra })).toString('base64url');
  const sig = crypto.createHmac('sha256', secret()).update(p).digest('base64url');
  return `${p}.${sig}`;
}
function readToken(req) {
  const h = req.headers.authorization || '';
  const t = h.startsWith('Bearer ') ? h.slice(7) : '';
  const [p, sig] = t.split('.');
  if (!p || !sig) return null;
  const exp = crypto.createHmac('sha256', secret()).update(p).digest('base64url');
  if (!safeEqual(exp, sig)) return null;
  try { const d = JSON.parse(Buffer.from(p, 'base64url').toString()); return d.exp > Date.now() ? d : null; } catch { return null; }
}
async function currentUser(req) {
  const t = readToken(req);
  if (!t) throw httpErr(401, 'Please sign in again');
  if (t.preview) {
    // Demo preview session: no account behind it, analysis only.
    return { id: 0, username: 'demo preview', role: 'user', status: 'active', plan: 'preview', expires_at: new Date(t.exp).toISOString(), preview: true };
  }
  const [u] = await db()`SELECT * FROM gp_users WHERE id = ${t.uid}`;
  if (!u) throw httpErr(401, 'This account no longer exists');
  // Single-device activation: a license-bound account only works on the device it was activated on.
  const device = String(req.headers['x-gp-device'] || '');
  if (u.device_id && u.role !== 'admin' && device !== u.device_id) throw httpErr(401, 'This VIP license is active on another device. Contact the administrator to move it.');
  return u;
}

/* ---------- Access rules ---------- */
// VIP Access (Owner Control OPEN/CLOSE): when CLOSED, VIP (lifetime) and 30-day users keep their accounts but get no access. Admins are never affected.
async function accessFull(u) {
  const a = access(u);
  if (a.ok && u.role !== 'admin' && (u.plan === 'lifetime' || u.plan === 'vip30')) {
    const st = await getSettings();
    if (st.vip_enabled === '0') return { ok: false, reason: 'vipclosed', message: 'VIP access is closed right now by the owner. Your account is kept; please try again later or contact the administrator.' };
  }
  return a;
}
function access(u) {
  if (u.status === 'pending') return { ok: false, reason: 'pending', message: 'Your account is waiting for approval. You will get access once it is reviewed.' };
  if (u.status === 'revoked') return { ok: false, reason: 'revoked', message: 'Your access has been revoked. Contact support.' };
  if (u.status === 'rejected') return { ok: false, reason: 'rejected', message: 'Your registration was not approved. Contact support.' };
  if (u.plan === 'preview') return { ok: true, preview: true };
  if (u.role === 'admin' || u.plan === 'lifetime') return { ok: true };
  if (u.plan === 'none') return { ok: false, reason: 'nokey', message: 'Your account has no license yet. Enter a VIP or demo license key.' };
  if (u.expires_at && new Date(u.expires_at) > new Date()) return { ok: true };
  const msg = u.plan === 'demo' ? 'Your 8-hour demo access has ended.' : u.plan === 'vip30' ? 'Your 30-day license has expired.' : 'Your license has expired.';
  return { ok: false, reason: 'expired', message: msg + ' Enter a new license key to continue.' };
}
function publicUser(u) {
  return { id: u.id, username: u.username, role: u.role, status: u.status, plan: u.plan,
    expires_at: u.expires_at, created_at: u.created_at, last_login: u.last_login, created_by: u.created_by, device_locked: !!u.device_id,
    full_name: u.full_name || null, contact: u.contact || null, requested: u.requested || null, assigned_key: u.assigned_key || null };
}
function normName(n) {
  const s = String(n || '').trim().toLowerCase();
  if (!/^[a-z0-9_.-]{3,32}$/.test(s)) throw httpErr(400, 'Username must be 3–32 characters: letters, numbers, dot, dash or underscore');
  return s;
}
function checkNewPw(p) {
  p = String(p || '');
  if (p.length < 6 || p.length > 128) throw httpErr(400, 'Password must be at least 6 characters');
  return p;
}

/* ---------- License keys ---------- */
function genKey(type) {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // 32 chars, no 0/O/1/I
  let s = '';
  for (const b of crypto.randomBytes(12)) s += alphabet[b % 32];
  return `GAIN-${KEY_TYPES[type]}-${s.slice(0, 4)}-${s.slice(4, 8)}-${s.slice(8, 12)}`;
}

async function setPlan(id, plan) {
  const sql = db();
  let r;
  switch (plan) {
    case 'admin': r = await sql`UPDATE gp_users SET role = 'admin', plan = 'admin', expires_at = NULL WHERE id = ${id} RETURNING *`; break;
    case 'lifetime': r = await sql`UPDATE gp_users SET role = 'user', plan = 'lifetime', expires_at = NULL WHERE id = ${id} RETURNING *`; break;
    case 'vip30': r = await sql`UPDATE gp_users SET role = 'user', plan = 'vip30', expires_at = GREATEST(COALESCE(expires_at, now()), now()) + interval '30 days' WHERE id = ${id} RETURNING *`; break;
    case 'demo': r = await sql`UPDATE gp_users SET role = 'user', plan = 'demo', expires_at = now() + interval '8 hours' WHERE id = ${id} RETURNING *`; break;
    default: r = await sql`UPDATE gp_users SET role = 'user', plan = 'none', expires_at = NULL WHERE id = ${id} RETURNING *`;
  }
  if (!r.length) throw httpErr(404, 'User not found');
  return r[0];
}

async function applyKey(u, keyStr, renewal = false) {
  const sql = db();
  const key = String(keyStr || '').trim().toUpperCase();
  if (!key) throw httpErr(400, 'Enter a license key');
  const [k] = await sql`SELECT * FROM gp_keys WHERE key = ${key}`;
  if (!k) throw httpErr(400, 'License key not found');
  if (k.revoked) throw httpErr(400, 'This license key has been revoked');
  if (k.redeemed_by != null) throw httpErr(400, 'This license key has already been used');
  if (k.type === 'demo' && u.plan !== 'none' && !renewal) throw httpErr(400, 'Demo keys are only for accounts that have never had a license');
  if (k.type !== 'admin' && (u.plan === 'lifetime' || u.role === 'admin')) throw httpErr(400, 'This account already has unlimited access');
  const claimed = await sql`UPDATE gp_keys SET redeemed_by = ${u.id}, redeemed_at = now()
    WHERE key = ${key} AND redeemed_by IS NULL AND revoked = false RETURNING type`;
  if (!claimed.length) throw httpErr(409, 'This license key was just used by someone else');
  if (k.type === 'vip30') {
    // Extend from the current expiry so unused days carry over.
    const [r] = await sql`UPDATE gp_users SET plan = 'vip30', expires_at = GREATEST(COALESCE(expires_at, now()), now()) + interval '30 days' WHERE id = ${u.id} RETURNING *`;
    return r;
  }
  return setPlan(u.id, k.type);
}

/* ---------- Deriv connection settings (App ID + data source are public; tokens are secret) ---------- */
const FEED_MODES = ['auto', 'public', 'legacy'];
async function getSettings() {
  const rows = await db()`SELECT key, value FROM gp_settings`;
  const o = { feed_mode: 'auto', deriv_app_id: '' };
  rows.forEach(r => { o[r.key] = r.value; });
  return o;
}
async function setSetting(key, value) {
  await db()`INSERT INTO gp_settings (key, value) VALUES (${key}, ${value})
    ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value`;
}

// Tokens are encrypted at rest with AES-256-GCM (key derived from AUTH_SECRET) and never returned to any browser.
function tokenKey() { return crypto.createHash('sha256').update(secret() + ':gp-deriv-tokens').digest(); }
function seal(text) {
  const iv = crypto.randomBytes(12);
  const c = crypto.createCipheriv('aes-256-gcm', tokenKey(), iv);
  const ct = Buffer.concat([c.update(text, 'utf8'), c.final()]);
  return [iv, c.getAuthTag(), ct].map(b => b.toString('base64')).join('.');
}
function unseal(sealed) {
  const [iv, tag, ct] = String(sealed).split('.').map(x => Buffer.from(x, 'base64'));
  const d = crypto.createDecipheriv('aes-256-gcm', tokenKey(), iv);
  d.setAuthTag(tag);
  return Buffer.concat([d.update(ct), d.final()]).toString('utf8');
}

// Checks a token against Deriv without placing any trade.
async function verifyToken(kind, token, appId) {
  if (kind === 'pat') {
    if (!appId) return { ok: false, msg: 'Set your Deriv App ID first. Personal access tokens need it.' };
    try {
      const r = await fetch('https://api.derivws.com/trading/v1/options/accounts', {
        headers: { Authorization: `Bearer ${token}`, 'Deriv-App-ID': String(appId), Accept: 'application/json' },
        signal: AbortSignal.timeout(10000)
      });
      let d = {}; try { d = await r.json(); } catch {}
      if (!r.ok) return { ok: false, msg: (d.errors && d.errors[0] && d.errors[0].message) || `Deriv answered HTTP ${r.status}` };
      const list = Array.isArray(d.data) ? d.data : (d.data && Array.isArray(d.data.accounts) ? d.data.accounts : []);
      const accounts = list.map(a => ({
        id: a.account_id || a.id || a.loginid,
        type: String(a.account_type || a.type || (a.is_virtual ? 'demo' : '')).toLowerCase() || (/^D/i.test(String(a.account_id || a.id || '')) ? 'demo' : ''),
        currency: a.currency || null, balance: a.balance ?? null
      })).filter(a => a.id);
      const ids = accounts.map(a => a.id).slice(0, 4);
      return { ok: true, accounts, msg: `Valid · ${accounts.length} account${accounts.length === 1 ? '' : 's'}${ids.length ? ' (' + ids.join(', ') + ')' : ''}` };
    } catch (e) { return { ok: false, msg: 'Could not reach the Deriv API' }; }
  }
  if (typeof WebSocket === 'undefined') return { ok: false, msg: 'This server has no WebSocket client. Set Node.js 22 in Vercel.' };
  return new Promise(resolve => {
    let ws, done = false;
    const finish = v => { if (done) return; done = true; clearTimeout(timer); try { ws.close(); } catch {} resolve(v); };
    const timer = setTimeout(() => finish({ ok: false, msg: 'Deriv did not answer in time' }), 10000);
    try { ws = new WebSocket(`wss://ws.derivws.com/websockets/v3?app_id=${encodeURIComponent(appId || '1089')}`); }
    catch { finish({ ok: false, msg: 'Could not open the Deriv legacy API' }); return; }
    ws.onopen = () => ws.send(JSON.stringify({ authorize: token }));
    ws.onmessage = ev => {
      let m = {}; try { m = JSON.parse(typeof ev.data === 'string' ? ev.data : String(ev.data)); } catch {}
      if (m.error) finish({ ok: false, msg: m.error.message || 'Token rejected' });
      else if (m.authorize) finish({ ok: true, accounts: [{ id: m.authorize.loginid, type: m.authorize.is_virtual ? 'demo' : 'real', currency: m.authorize.currency || null, balance: m.authorize.balance ?? null }],
        msg: `Valid · ${m.authorize.loginid}${m.authorize.is_virtual ? ' (demo)' : ' (real)'}` });
    };
    ws.onerror = () => finish({ ok: false, msg: 'Could not reach the Deriv legacy API' });
  });
}

/* ---------- Owner desk: keys generated for a specific person ---------- */
const ACCESS_PLANS = ['lifetime', 'vip30', 'demo'];
async function assignNewKey(u, plan, by) {
  const sql = db();
  if (!ACCESS_PLANS.includes(plan)) throw httpErr(400, 'Choose VIP lifetime, 30 days or demo access');
  const key = genKey(plan);
  await sql`INSERT INTO gp_keys (key, type, created_by, note, assigned_to) VALUES (${key}, ${plan}, ${by}, ${u.full_name || u.username}, ${u.id})`;
  const [r] = await sql`UPDATE gp_users SET assigned_key = ${key}, requested = ${plan} WHERE id = ${u.id} RETURNING *`;
  return { user: r, key, plan };
}
async function uniqueUsername(base) {
  const sql = db();
  const b = (String(base || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '.').replace(/^\.+|\.+$/g, '') || 'user').slice(0, 24);
  const name = b.length >= 3 ? b : (b + '.user');
  const [x] = await sql`SELECT id FROM gp_users WHERE username = ${name}`;
  return x ? `${name}.${crypto.randomBytes(2).toString('hex')}` : name;
}


/* ================= DBot XML reader ================= */

// Reads a Deriv DBot (Blockly) XML file and extracts what the server needs to run it:
// market, contract type, duration, stake, prediction, and (when it matches a known pattern)
// the bot's own "count digits in the last N ticks" entry rule.
// Anything else in the XML (custom logic, stake changes such as martingale) is reported, not copied.

const SUPPORTED = {
  DIGITOVER: 'Digit Over', DIGITUNDER: 'Digit Under', DIGITMATCH: 'Digit Matches', DIGITDIFF: 'Digit Differs',
  DIGITEVEN: 'Digit Even', DIGITODD: 'Digit Odd', CALL: 'Rise', PUT: 'Fall',
  DIGITEVENODD: 'Even/Odd (both sides)', DIGITOVERUNDER: 'Over/Under (both sides)', CALLPUT: 'Rise/Fall (both sides)'
};
const NEEDS_BARRIER = ['DIGITOVER', 'DIGITUNDER', 'DIGITMATCH', 'DIGITDIFF', 'DIGITOVERUNDER'];

const Q = `['"]`;
const num = s => { const n = Number(String(s).trim()); return Number.isFinite(n) ? n : null; };

function field(xml, name) {
  const m = xml.match(new RegExp(`<field name=${Q}${name}${Q}[^>]*>([^<]*)</field>`));
  return m ? m[1].trim() : null;
}

// First numeric value assigned to each variable (normally in the INITIALIZATION block).
function varInits(xml) {
  const out = {};
  const re = new RegExp(`<block type=${Q}variables_set${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}([^'"]+)${Q}[^>]*>[^<]*</field>\\s*<value name=${Q}VALUE${Q}>\\s*<block type=${Q}math_number${Q}[^>]*>\\s*<field name=${Q}NUM${Q}>([^<]*)</field>`, 'g');
  let m;
  while ((m = re.exec(xml))) if (!(m[1] in out)) out[m[1]] = num(m[2]);
  return out;
}

// Value of an input such as AMOUNT / DURATION / PREDICTION: a variable, a number block, or the shadow default.
function inputValue(xml, name, inits) {
  const i = xml.search(new RegExp(`<value name=${Q}${name}${Q}>`));
  if (i < 0) return null;
  const rest = xml.slice(i);
  const seg = rest.slice(0, rest.indexOf('</value>') + 8);
  const vg = seg.match(new RegExp(`variables_get${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}([^'"]+)${Q}`));
  if (vg && inits[vg[1]] != null) return inits[vg[1]];
  const nb = seg.match(new RegExp(`<block type=${Q}math_number(?:_positive)?${Q}[^>]*>\\s*<field name=${Q}NUM${Q}>([^<]*)<`));
  if (nb) return num(nb[1]);
  const sh = seg.match(new RegExp(`<field name=${Q}NUM${Q}>([^<]*)<`));
  return sh ? num(sh[1]) : null;
}

// Detects: take the last N digits, count those <op> X, enter when count <op> threshold.
function detectRule(xml, inits) {
  if (!/lastDigitList/.test(xml)) return null;
  const sub = xml.match(new RegExp(`lists_getSublist[\\s\\S]*?<field name=${Q}WHERE1${Q}>FROM_END</field>[\\s\\S]*?<value name=${Q}AT1${Q}>\\s*<block type=${Q}variables_get${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}([^'"]+)${Q}`));
  const loop = xml.match(new RegExp(`controls_forEach${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}([^'"]+)${Q}`));
  const cmpRe = new RegExp(`<block type=${Q}logic_compare${Q}[^>]*>\\s*<field name=${Q}OP${Q}>(\\w+)</field>\\s*<value name=${Q}A${Q}>\\s*<block type=${Q}variables_get${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}([^'"]+)${Q}[^>]*>[^<]*</field>\\s*</block>\\s*</value>\\s*<value name=${Q}B${Q}>\\s*<block type=${Q}variables_get${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}([^'"]+)${Q}`, 'g');
  const cmps = [...xml.matchAll(cmpRe)];
  if (!sub || !loop) return null;
  const digitCmp = cmps.find(c => c[2] === loop[1]);
  const countCmp = cmps.find(c => c !== digitCmp && ['GT', 'GTE', 'EQ', 'LT', 'LTE'].includes(c[1]));
  if (!digitCmp || !countCmp) return null;
  const rule = { window: inits[sub[1]], digitOp: digitCmp[1], value: inits[digitCmp[3]], countOp: countCmp[1], threshold: inits[countCmp[3]] };
  return Object.values(rule).every(v => v != null) ? rule : null;
}

function describeRule(r) {
  if (!r) return null;
  const op = { GT: '>', GTE: '≥', LT: '<', LTE: '≤', EQ: '=', NEQ: '≠' };
  return `enter when digits ${op[r.digitOp] || r.digitOp} ${r.value} appear ${op[r.countOp] || r.countOp} ${r.threshold} times in the last ${r.window} ticks`;
}

function parseDbotXml(xml) {
  xml = String(xml || '');
  if (!/<xml[\s>]/.test(xml) || !/trade_definition/.test(xml)) throw new Error('This is not a DBot XML file');
  const inits = varInits(xml);
  const symbol = field(xml, 'SYMBOL_LIST');
  const purchases = [...xml.matchAll(new RegExp(`<field name=${Q}PURCHASE_LIST${Q}>([^<]*)</field>`, 'g'))].map(m => m[1].trim());
  const set = new Set(purchases);
  // Bots that buy both sides of a pair (e.g. Even or Odd depending on the tick) follow both directions of the tool's signal.
  const contract_type = set.has('DIGITEVEN') && set.has('DIGITODD') ? 'DIGITEVENODD' : set.has('DIGITOVER') && set.has('DIGITUNDER') ? 'DIGITOVERUNDER' : set.has('CALL') && set.has('PUT') ? 'CALLPUT' : (purchases[0] || null);
  const warnings = [];
  if (!symbol) throw new Error('No market (SYMBOL_LIST) found in the XML');
  if (!contract_type) throw new Error('No purchase block found in the XML');
  if (!SUPPORTED[contract_type]) throw new Error(`Contract type ${contract_type} isn't supported yet`);
  if (set.size > 1 && !['DIGITEVENODD', 'DIGITOVERUNDER', 'CALLPUT'].includes(contract_type)) warnings.push(`The XML buys several contract types (${[...new Set(purchases)].join(', ')}). Only ${contract_type} is used.`);
  const duration = inputValue(xml, 'DURATION', inits) || 1;
  const duration_unit = field(xml, 'DURATIONTYPE_LIST') || 't';
  const stake = inputValue(xml, 'AMOUNT', inits) || 1;
  const prediction = NEEDS_BARRIER.includes(contract_type) ? inputValue(xml, 'PREDICTION', inits) : null;
  if (NEEDS_BARRIER.includes(contract_type) && (prediction == null || prediction < 0 || prediction > 9)) throw new Error('No valid prediction digit found in the XML');
  if (duration_unit !== 't') warnings.push(`Duration unit "${duration_unit}" is used as-is; GainPlus+ signals are tick-based.`);
  const stakeVar = (xml.match(new RegExp(`<value name=${Q}AMOUNT${Q}>[\\s\\S]*?variables_get${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}([^'"]+)${Q}`)) || [])[1];
  if (stakeVar) {
    const sets = (xml.match(new RegExp(`<field name=${Q}VAR${Q} id=${Q}${stakeVar}${Q}`, 'g')) || []).length;
    const changes = new RegExp(`math_change${Q}[^>]*>\\s*<field name=${Q}VAR${Q} id=${Q}${stakeVar}${Q}`).test(xml);
    if (changes || sets > 2) warnings.push('The XML changes its stake while running (e.g. martingale). The server uses a fixed stake instead.');
  }
  const rule = detectRule(xml, inits);
  if (!rule && /lastDigitList|logic_compare/.test(xml)) warnings.push("The XML's own entry logic wasn't recognised, so only GainPlus+ signals can trigger it.");
  return {
    symbol, contract_type, contract_label: SUPPORTED[contract_type], duration: Math.max(1, Math.round(duration)),
    duration_unit, stake, barrier: prediction == null ? null : Math.round(prediction), rule, rule_text: describeRule(rule), warnings
  };
}

