        <div class="dk-meta">${u.contact ? `<span>${/@/.test(u.contact) ? ICO.mail : ICO.phone}${esc(u.contact)}</span>` : '<span class="void">No phone or email saved</span>'}<span>• Registered: ${fmtDate(u.created_at)}</span>${u.status === 'active' && (u.plan === 'vip30' || u.plan === 'demo') ? `<span>• ${expLine(u)}</span>` : ''}</div>
