/* ---------- Router: one file serves the app page and the whole API ---------- */
class ResShim {
  constructor() { this.code = 200; this.body = ''; this.headers = { 'Content-Type': 'application/json; charset=utf-8' }; }
  status(c) { this.code = c; return this; }
  setHeader(k, v) { this.headers[k] = v; return this; }
  json(o) { this.body = JSON.stringify(o); return this; }
  toResponse() { return new Response(this.body, { status: this.code, headers: this.headers }); }
}
const PAGE_HEADERS = {
  'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache',
  'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'strict-origin-when-cross-origin'
};

export const config = { runtime: 'nodejs' };

export default async function middleware(request) {
  const url = new URL(request.url);
  const path = url.pathname.replace(/\/+$/, '') || '/';
  if (path === '/api/auth' || path === '/api/admin') {
    let body = {};
    if (request.method === 'POST') { try { body = await request.json(); } catch { body = {}; } }
    const headers = {}; request.headers.forEach((v, k) => { headers[k.toLowerCase()] = v; });
    const res = new ResShim();
    await (path === '/api/auth' ? authHandler : adminHandler)({ method: request.method, headers, body }, res);
    return res.toResponse();
  }
  if (path === '/' || path === '/index.html') return new Response(APP_HTML, { headers: PAGE_HEADERS });
  if (path === '/favicon.ico') return new Response(null, { status: 204 });
  if (path.startsWith('/api/')) return new Response(JSON.stringify({ error: 'Not found' }), { status: 404, headers: { 'Content-Type': 'application/json' } });
  // Any other path opens the app (it uses #/ routes).
  return new Response(APP_HTML, { headers: PAGE_HEADERS });
}
